#include "postquantiquecoin/blockchain/ChainParams.h"
#include "postquantiquecoin/core/Constants.h"
namespace pqc { ChainParams ChainParams::Mainnet(){ return {std::string(constants::PROJECT_NAME),std::string(constants::COIN_SYMBOL),constants::COIN_DECIMALS,constants::MAX_SUPPLY_COINS,constants::MAX_SUPPLY_ATOMS,constants::TARGET_BLOCK_TIME_SECONDS,constants::DIFFICULTY_ADJUSTMENT_INTERVAL,constants::COINBASE_MATURITY,constants::INITIAL_SUBSIDY_ATOMS,constants::HALVING_INTERVAL,0x207fffff,"DoubleSha256 header hash; SHA3-256 used for addresses and signing domain digests","ML-DSA-65","ML-KEM-768",""}; } uint64_t ChainParams::GetBlockSubsidy(uint64_t height,uint64_t alreadyMinted) const { if(alreadyMinted>=maxSupplyAtoms) return 0; uint64_t halvings=height/halvingInterval; uint64_t subsidy = halvings>=64 ? 0 : (initialSubsidyAtoms >> halvings); uint64_t remaining=maxSupplyAtoms-alreadyMinted; return subsidy>remaining?remaining:subsidy; } }
